const getContent = (json) => 
  json?.output?.[0]?.content?.[0]?.text ||
  json?.message?.content || 
  json?.content?.[0]?.text || 
  json?.text || 
  '';

const allItems = $input.all();

let companyIntel = '', resumeFeedback = '', coverLetter = '', emailContent = '';

for (const item of allItems) {
  const content = getContent(item.json);
  if (!content) continue;

  if (content.includes('WHAT THEY DO') || content.includes('TALKING POINTS')) {
    companyIntel = content;
  } else if (content.includes('SUITABILITY SCORE') || content.includes('STRONG MATCHES')) {
    resumeFeedback = content;
  } else if (content.includes('SUBJECT:') && content.includes('BODY:')) {
    emailContent = content;
  } else if (content.length > coverLetter.length && content.length > 200) {
    coverLetter = content;
  }
}

const triggerData = $('Trigger — Fill Job Details1').first().json;

const subjectMatch = emailContent.match(/SUBJECT:\s*(.+)/i);
const bodyMatch = emailContent.match(/BODY:\s*([\s\S]+)/i);
const subject = subjectMatch ? subjectMatch[1].trim() : 'Application for ' + triggerData['Job Title'] + ' at ' + triggerData['Company Name'];
const body = bodyMatch ? bodyMatch[1].trim() : emailContent;

const scoreMatch = resumeFeedback.match(/SUITABILITY SCORE[:\s]+(\d+)/i);
const suitabilityScore = scoreMatch ? scoreMatch[1] + '/10' : 'N/A';

const sendOption = triggerData['Send the application email'] || '';
const sendEmail = sendOption === 'Yes — send it automatically';

const followUpDate = new Date();
followUpDate.setDate(followUpDate.getDate() + 7);
const followUpStr = followUpDate.toISOString().split('T')[0];

return [{
  json: {
    emailSubject: subject,
    emailBody: body,
    companyIntel,
    resumeFeedback,
    coverLetter,
    sendEmail,
    suitabilityScore,
    followUpDate: followUpStr,
    hiringManagerEmail: triggerData['Hiring Manager Email'],
    jobTitle: triggerData['Job Title'],
    companyName: triggerData['Company Name'],
    emailSentStatus: sendEmail ? 'Yes' : 'No',
    fullDigest: '============================\n🏢 AGENT 1 — COMPANY INTEL\n============================\n' + companyIntel +
      '\n\n============================\n📊 AGENT 2 — RESUME FEEDBACK\n============================\n' + resumeFeedback +
      '\n\n============================\n📝 AGENT 3 — COVER LETTER\n============================\n' + coverLetter +
      '\n\n============================\n📧 AGENT 4 — APPLICATION EMAIL\n============================\nSUBJECT: ' + subject + '\n\n' + body
  }
}];

