const raw = $input.first().json.data || '';

// Strip all HTML tags, collapse whitespace
const text = raw
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 3000); // keep first 3000 chars only

return [{ json: { cleanText: text } }];
